  {
    "taxonId": 58893,
    "summary": "A fast-growing annual plant native to North America. Its spreading stems form ground-hugging mats, and its small hairy leaves usually bear a central brown spot. Broken leaves or stems release poisonous milky sap that can irritate skin and cause stomach irritation and vomiting if swallowed.",
    "humanEdibility": "no",
    "edibilityNote": "The poisonous milky sap has been ingested medicinally as a laxative or to induce vomiting, but can irritate the stomach and cause vomiting.",
    "evidence": {
      "summary": ["s1:p1", "s1:p3", "s1:p4", "s1:p11"],
      "humanEdibility": ["s1:p10", "s1:p11"]
    }
  },
  {
    "taxonId": 371995,
    "summary": "A bulbous flowering plant native from the Balearic Islands through the Mediterranean and western Asia to Tajikistan. It retreats to its bulb in summer, then produces glossy green leaves and deep yellow flowers in autumn. The leaves remain through winter.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p1", "s1:p4", "s1:p5", "s1:p7"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 162839,
    "summary": "A woody succulent shrub native to Madagascar. It has densely spiny stems and fleshy leaves concentrated on new growth, though its form varies among cultivars. Small flowers framed by conspicuous red, pink or white bracts may appear throughout the year.",
    "humanEdibility": "no",
    "edibilityNote": "Its moderately poisonous sap causes severe stomach pain, mouth and throat irritation, and vomiting if ingested.",
    "evidence": {
      "summary": ["s1:p1", "s1:p4", "s1:p5"],
      "humanEdibility": ["s1:p6"]
    }
  },
  {
    "taxonId": 60879,
    "summary": "A pantropical creeping vine found on sandy tropical shores of the Atlantic, Pacific and Indian oceans. It sends long runners across upper beaches and dunes, bearing two-lobed leaves and pink flowers with dark centres. Its saltwater-resistant floating seeds enable ocean dispersal.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p1", "s1:p3", "s1:p5", "s1:p6"],
      "humanEdibility": []
    }
  },
