    "taxonId": 524877,
    "summary": "A flowering plant native to mainland Portugal and belonging to the carrot family.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p1", "s1:p4", "s1:p5"],
      "humanEdibility": []
    }
